/* Enforce hidden attribute overriding display declarations */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #181425;
  --color-card: #262b44;
  --color-border: #ffbe44;
  --color-text: #f4f4f4;
  --color-accent: #00e436;
  --color-btn: #3a4466;
  --color-btn-hover: #5a6988;
  --color-btn-active: #21253a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: 'Courier New', Courier, monospace, system-ui;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.quiz-wrapper {
  width: 100%;
  max-width: 520px;
  background: var(--color-card);
  border: 4px solid var(--color-border);
  box-shadow: 6px 6px 0px #000000;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.quiz-header {
  border-bottom: 2px dashed var(--color-border);
  padding-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  text-align: center;
}

.pixel-title {
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--color-border);
  text-shadow: 2px 2px 0px #000;
}

.status-bar {
  display: flex;
  justify-content: space-around;
  background: #141724;
  padding: 8px 12px;
  border: 2px solid #3a4466;
}

.status-item {
  font-weight: bold;
  letter-spacing: 1px;
}

.status-item .label {
  color: #8b9bb4;
  font-size: 0.85rem;
  margin-right: 6px;
}

.status-item .value {
  color: var(--color-accent);
  font-size: 1.25rem;
}

.card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  text-align: center;
}

.description {
  line-height: 1.5;
  color: #c0cbdc;
  font-size: 1.05rem;
}

.question-meta {
  width: 100%;
  display: flex;
  justify-content: flex-start;
}

.badge {
  background: #141724;
  border: 1px solid var(--color-border);
  color: var(--color-border);
  font-size: 0.85rem;
  padding: 4px 8px;
  font-weight: bold;
}

.question-title {
  font-size: 1.25rem;
  line-height: 1.4;
  min-height: 54px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.answers-grid {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.pixel-btn {
  appearance: none;
  background-color: var(--color-btn);
  color: var(--color-text);
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 16px;
  border: 2px solid #f4f4f4;
  box-shadow: 3px 3px 0px #000000;
  cursor: pointer;
  text-align: center;
  transition: none;
  outline: none;
}

.pixel-btn:hover {
  background-color: var(--color-btn-hover);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--color-border);
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px #000000;
  background-color: var(--color-btn-active);
}

.primary-btn {
  background-color: #216a3e;
  border-color: var(--color-accent);
  color: #fff;
  width: 100%;
  max-width: 240px;
}

.primary-btn:hover {
  background-color: #28824c;
}

.final-score-box {
  background: #141724;
  border: 2px solid var(--color-border);
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.final-score-box .label {
  font-size: 0.9rem;
  color: #8b9bb4;
}

.final-score {
  font-size: 2.2rem;
  color: var(--color-accent);
  font-weight: bold;
}

.result-msg {
  font-size: 1.15rem;
  color: #ffbe44;
}

@media (min-width: 480px) {
  .answers-grid {
    grid-template-columns: 1fr 1fr;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const QUIZ_QUESTIONS = [
    {
      question: 'Which company created the classic arcade game Pong?',
      answers: ['Nintendo', 'Atari', 'Sega', 'Namco'],
      correct: 1
    },
    {
      question: 'What is the highest possible score in classic Pac-Man?',
      answers: ['999,990', '1,000,000', '3,333,360', '5,000,000'],
      correct: 2
    },
    {
      question: 'What color is the ghost named Blinky in Pac-Man?',
      answers: ['Red', 'Pink', 'Cyan', 'Orange'],
      correct: 0
    },
    {
      question: 'What was Mario originally known as in Donkey Kong?',
      answers: ['Plumber', 'Jumpman', 'Luigi', 'Red Hat'],
      correct: 1
    },
    {
      question: 'Which console introduced the Game Boy in 1989?',
      answers: ['Sony', 'Bandai', 'Nintendo', 'Atari'],
      correct: 2
    }
  ];

  const TOTAL_TIME = 60;
  let currentQuestionIndex = 0;
  let score = 0;
  let remainingTime = TOTAL_TIME;
  let timerInterval = null;

  // Elements
  const timerDisplay = document.getElementById('timer-display');
  const scoreDisplay = document.getElementById('score-display');
  const startScreen = document.getElementById('start-screen');
  const quizScreen = document.getElementById('quiz-screen');
  const resultScreen = document.getElementById('result-screen');
  const questionProgress = document.getElementById('question-progress');
  const questionText = document.getElementById('question-text');
  const answersContainer = document.getElementById('answers-container');
  const answerButtons = answersContainer.querySelectorAll('.answer-btn');
  const startBtn = document.getElementById('start-btn');
  const restartBtn = document.getElementById('restart-btn');
  const resultTitle = document.getElementById('result-title');
  const resultMessage = document.getElementById('result-message');
  const finalScoreDisplay = document.getElementById('final-score-display');

  function startQuiz() {
    score = 0;
    currentQuestionIndex = 0;
    remainingTime = TOTAL_TIME;
    scoreDisplay.textContent = score;
    timerDisplay.textContent = remainingTime;

    startScreen.hidden = true;
    resultScreen.hidden = true;
    quizScreen.hidden = false;

    loadQuestion();
    startTimer();
  }

  function startTimer() {
    clearInterval(timerInterval);
    timerInterval = setInterval(() => {
      remainingTime -= 1;
      timerDisplay.textContent = remainingTime;

      if (remainingTime <= 0) {
        clearInterval(timerInterval);
        endQuiz(false);
      }
    }, 1000);
  }

  function loadQuestion() {
    const current = QUIZ_QUESTIONS[currentQuestionIndex];
    questionProgress.textContent = `Question ${currentQuestionIndex + 1} of ${QUIZ_QUESTIONS.length}`;
    questionText.textContent = current.question;

    answerButtons.forEach((button, index) => {
      button.textContent = current.answers[index];
    });

    if (answerButtons.length > 0) {
      answerButtons[0].focus();
    }
  }

  function handleAnswer(selectedIndex) {
    const current = QUIZ_QUESTIONS[currentQuestionIndex];
    if (selectedIndex === current.correct) {
      score += 1;
      scoreDisplay.textContent = score;
    }

    currentQuestionIndex += 1;

    if (currentQuestionIndex < QUIZ_QUESTIONS.length) {
      loadQuestion();
    } else {
      endQuiz(true);
    }
  }

  function endQuiz(completedAll) {
    clearInterval(timerInterval);
    quizScreen.hidden = true;
    startScreen.hidden = true;
    resultScreen.hidden = false;

    if (completedAll) {
      resultTitle.textContent = 'Quiz Completed!';
      resultMessage.textContent = score === QUIZ_QUESTIONS.length
        ? 'Perfect score! True retro master!'
        : 'Great run! Can you get 5 out of 5?';
    } else {
      resultTitle.textContent = "Time's Up!";
      resultMessage.textContent = 'You ran out of time!';
    }

    finalScoreDisplay.textContent = `${score} / ${QUIZ_QUESTIONS.length}`;
    restartBtn.focus();
  }

  // Event Listeners
  startBtn.addEventListener('click', startQuiz);
  restartBtn.addEventListener('click', startQuiz);

  answersContainer.addEventListener('click', (event) => {
    const target = event.target.closest('.answer-btn');
    if (!target) return;
    const chosenIndex = parseInt(target.getAttribute('data-index'), 10);
    handleAnswer(chosenIndex);
  });
});
